const IMG = {};
const loadImg = src => new Promise((ok, no) => { const i = new Image(); i.onload = () => ok(i); i.onerror = no; i.src = src; });
const ASSETS = (async () => {
  LAY = JSON.parse(JSON.stringify(REEL_LAYOUT));
  [IMG.A, IMG.B] = await Promise.all(['A', 'B'].map(n => loadImg(DIR + n + '.png')));
  IMG.names = await Promise.all(LAY.presets.map((_, i) => loadImg(DIR + `name-${i}.png`)));
  SCOPE = await loadScope();
  // the colours behind the two readouts, so they can be redrawn from the state
  const c = mk(IMG.A.width, IMG.A.height).getContext('2d'); c.drawImage(IMG.A, 0, 0);
  const px = (x, y) => { const d = c.getImageData(Math.round(x * 3), Math.round(y * 3), 1, 1).data; return `rgb(${d[0]},${d[1]},${d[2]})`; };
  LAY.readBg = px(LAY.arpRead[0] - 4, LAY.arpRead[1] + LAY.arpRead[3] / 2);
  LAY.bpmBg = px(LAY.bpm[0] + 4, LAY.bpm[1] + LAY.bpm[3] / 2);
})();

// ============================================================ THE PANEL ==
// State at time t: the last patch loaded, every slider move since, the keys
