  ctx.save(); ctx.shadowBlur = 80; ctx.shadowColor = 'rgba(0,0,0,0.7)'; ctx.shadowOffsetY = 26;
  rrect(0, 0, L.size[0], L.size[1], 8); ctx.fillStyle = '#1b1b1e'; ctx.fill(); ctx.restore();
  ctx.drawImage(IMG.A, 0, 0, L.size[0], L.size[1]);
  const crop = (im, r) => ctx.drawImage(im, r[0] * 3, r[1] * 3, r[2] * 3, r[3] * 3, r[0], r[1], r[2], r[3]);
  for (const sg of L.segs) { const r = sg.r[st.v[sg.id] | 0]; if (r) crop(IMG.B, r); }
